class GuardrailChain:
    """Runs guardrails sequentially; block stops the chain."""

    def __init__(self, steps: list[GuardrailStepConfig]) -> None:
        self._steps = steps

    async def process(self, text: str, context: dict[str, Any] | None = None) -> GuardrailResult:
        current = text
        warnings: list[str] = []
        redacted: list[str] = []
        ctx = dict(context or {})
        for step in self._steps:
            plugin = _plugin_factory(step.plugin)
            action = str(step.params.get("action", "warn"))
            params = {**step.params, "_action": action}
            result = await plugin.run(current, ctx, **params)
            current = result.text
            warnings.extend(result.warnings)
            redacted.extend(result.redacted_fields)
            if result.blocked:
                return GuardrailResult(
                    text=current,
                    blocked=True,
                    warnings=warnings,
                    redacted_fields=redacted,
                )
        return GuardrailResult(
            text=current,
            blocked=False,
            warnings=warnings,
            redacted_fields=redacted,
        )
